package com.example.cdn;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.cache.CacheManager;
import org.springframework.cache.concurrent.ConcurrentMapCacheManager;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.ResponseEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import javax.servlet.http.HttpServletRequest;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

@SpringBootApplication
@EnableCaching
public class CdnProxyApplication {
    public static void main(String[] args) {
        SpringApplication.run(CdnProxyApplication.class, args);
    }
}

@Configuration
class CacheConfig {
    @Bean
    public CacheManager cacheManager() {
        return new ConcurrentMapCacheManager("pages", "assets");
    }
}

@RestController
@RequestMapping("/api")
class PageController {

    private static final Map<String, String> SCRIPT_REGISTRY = new ConcurrentHashMap<>();

    static {
        SCRIPT_REGISTRY.put("analytics", "https://cdn.example.com/analytics-v3.2.1.min.js");
        SCRIPT_REGISTRY.put("tracking", "https://cdn.example.com/tracking-v1.8.0.min.js");
        SCRIPT_REGISTRY.put("utils", "https://cdn.example.com/utils-v2.1.0.min.js");
    }

    @GetMapping("/page")
    @Cacheable(value = "pages", key = "#request.getHeader('X-Forwarded-Host') ?: 'default'")
    public ResponseEntity<String> getPage(HttpServletRequest request,
                                          @RequestParam(value = "cb", required = false) String cacheBuster,
                                          @RequestParam(value = "lang", defaultValue = "en") String lang) {

        String forwardedHost = request.getHeader("X-Forwarded-Host");
        String baseUrl = (forwardedHost != null) ? "https://" + forwardedHost : "https://www.example.com";

        // Build page with dynamic script references
        StringBuilder html = new StringBuilder();
        html.append("<!DOCTYPE html>\n<html lang=\"").append(sanitizeLang(lang)).append("\">\n");
        html.append("<head>\n");
        html.append("  <meta charset=\"UTF-8\">\n");
        html.append("  <base href=\"").append(baseUrl).append("/\">\n");
        html.append("  <title>Dashboard</title>\n");

        // Load scripts from registry
        for (Map.Entry<String, String> entry : SCRIPT_REGISTRY.entrySet()) {
            html.append("  <script src=\"").append(entry.getValue()).append("\" ");
            html.append("crossorigin=\"anonymous\"></script>\n");
        }

        html.append("</head>\n<body>\n");
        html.append("  <div id=\"app\">Loading...</div>\n");
        html.append("  <script>window.__BASE_URL = '").append(baseUrl).append("';</script>\n");
        html.append("</body>\n</html>");

        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.TEXT_HTML);
        headers.setCacheControl("public, max-age=300");
        headers.set("Vary", "Accept-Language");

        return ResponseEntity.ok().headers(headers).body(html.toString());
    }

    @PostMapping("/scripts/register")
    public ResponseEntity<String> registerScript(@RequestParam String name,
                                                  @RequestParam String url) {
        // Internal API - only accessible from management network
        if (!url.startsWith("https://cdn.example.com/")) {
            return ResponseEntity.badRequest().body("Invalid CDN URL");
        }
        SCRIPT_REGISTRY.put(name, url);
        return ResponseEntity.ok("Registered");
    }

    private String sanitizeLang(String lang) {
        return lang.replaceAll("[^a-zA-Z-]", "");
    }
}
